create table xxventuri.xx_test_tally_invoice (
    batch_number         varchar2(250 byte),
    invoice_id           varchar2(250 byte),
    invoice_number       varchar2(250 byte),
    invoice_date         timestamp(6),
    customer_id          varchar2(250 byte),
    customer_name        varchar2(255 byte),
    po_reference         varchar2(255 byte),
    billing_location     varchar2(250 byte),
    sales_order_id       number,
    sales_order_number   varchar2(250 byte),
    sales_order_date     timestamp(6),
    invoice_value        varchar2(250 byte),
    product_id           number,
    product_code         varchar2(255 byte),
    customer_part_ref    varchar2(255 byte),
    invoice_qty          varchar2(250 byte),
    invoice_unit_price   varchar2(250 byte),
    invoice_uom          varchar2(20 byte),
    tax_amount           varchar2(250 byte),
    total_amount         varchar2(250 byte),
    created_by           varchar2(255 byte),
    created_date         timestamp(6),
    updated_by           varchar2(255 byte),
    updated_date         timestamp(6),
    status               varchar2(10 byte),
    batch_sequence       number,
    last_receipt_date    timestamp(6),
    last_receipt_amount  varchar2(200 byte),
    tally_transaction_id number
);


